import * as THREE from 'three';

// Ruler positions are stored in wall-local metres, never in screen pixels.
import {rulerMetrics} from './ruler-math.js';
export function createRuler({scene,camera,renderer,controls,sectors,walls,holds,defs,onActivate,beforeChange}){
 const canvas=renderer.domElement,button=document.querySelector('#rulerToggle'),label=document.querySelector('#rulerLabel'),readout=document.querySelector('#rulerReadout'),hint=document.querySelector('#rulerHint');
 let active=false,data=null,hover=null,drag=null,down=null;
 const ray=new THREE.Raycaster(),mouse=new THREE.Vector2(),group=new THREE.Group();scene.add(group);group.visible=false;
 const accent=new THREE.MeshBasicMaterial({color:'#7852ad',depthTest:false,depthWrite:false});
 const lineMaterial=new THREE.LineDashedMaterial({color:'#76539b',dashSize:.055,gapSize:.025,depthTest:false,depthWrite:false});
 const line=new THREE.Line(new THREE.BufferGeometry(),lineMaterial);group.add(line);
 const ticks=new THREE.LineSegments(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#76539b',depthTest:false,depthWrite:false}));group.add(ticks);
 const base=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineDashedMaterial({color:'#ad92cf',dashSize:.035,gapSize:.04,transparent:true,opacity:.65,depthTest:false,depthWrite:false}));group.add(base);
 const arc=new THREE.Line(new THREE.BufferGeometry(),new THREE.LineBasicMaterial({color:'#ad92cf',depthTest:false,depthWrite:false}));group.add(arc);
 const ends=[0,1].map(i=>{const m=new THREE.Mesh(new THREE.SphereGeometry(1,20,12),accent);m.userData.endpoint=i;group.add(m);const rim=new THREE.Mesh(new THREE.TorusGeometry(1.22,.08,8,32),accent);m.add(rim);return m});
 group.traverse(o=>o.renderOrder=1100);
 const v=a=>new THREE.Vector3(a[0],a[1],.14);
 function setLine(obj,points){obj.geometry.dispose();obj.geometry=new THREE.BufferGeometry().setFromPoints(points);if(obj.isLine)obj.computeLineDistances()}
 function cast(e,objects){const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);return ray.intersectObjects(objects,false)}
 function point(e,si=null){const hits=cast(e,[...holds,...walls]);const hit=hits.find(h=>h.object.userData.si!==undefined||h.face?.normal.z>.9);if(!hit)return null;const wallId=hit.object.userData.si??hit.object.userData.sector;if(si!==null&&wallId!==si)return null;const p=sectors[wallId].face.worldToLocal(hit.point.clone());return{sector:wallId,point:[THREE.MathUtils.clamp(p.x,-sectors[wallId].width/2,sectors[wallId].width/2),THREE.MathUtils.clamp(p.y,0,defs[wallId].h)]}}
 function planePoint(e,si){cast(e,[]);const face=sectors[si].face;face.updateWorldMatrix(true,false);const plane=new THREE.Plane().setFromNormalAndCoplanarPoint(new THREE.Vector3(0,0,1).transformDirection(face.matrixWorld),face.localToWorld(new THREE.Vector3(0,0,.14)));const hit=ray.ray.intersectPlane(plane,new THREE.Vector3());if(!hit)return null;face.worldToLocal(hit);return[THREE.MathUtils.clamp(hit.x,-sectors[si].width/2,sectors[si].width/2),THREE.MathUtils.clamp(hit.y,0,defs[si].h)]}
 function status(){button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));document.body.classList.toggle('measuring',active);hint.hidden=!active;hint.textContent=!data?'Click the first point on a wall':!data.b?'Click a second point on the same wall · Esc to cancel':'Drag either endpoint · Angle from wall horizontal · Esc to finish';}
 function setActive(value){if(value&&!active)onActivate();active=value;if(!value){cancelDrag();hover=null;if(data&&!data.b)data=null}status();update()}
 function cancelDrag(){if(drag){data[drag.index?'b':'a']=drag.original;drag=null}controls.enabled=true;down=null}
 function clear(){if(data)beforeChange();cancelDrag();data=null;hover=null;status();update()}
 button.onclick=()=>setActive(!active);document.querySelector('#clearRuler').onclick=clear;document.querySelector('#newRuler').onclick=()=>{clear();setActive(true)};
 function stop(e){e.preventDefault();e.stopImmediatePropagation()}
 canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0)return;const hit=data&&data.b?cast(e,ends)[0]:null;down={x:e.clientX,y:e.clientY,id:e.pointerId};if(hit){const index=hit.object.userData.endpoint;drag={index,original:[...(index?data.b:data.a)],changed:false};controls.enabled=false;canvas.setPointerCapture(e.pointerId);stop(e);return}if(!data||!data.b){controls.enabled=false;canvas.setPointerCapture(e.pointerId);stop(e)}}, {capture:true});
 canvas.addEventListener('pointermove',e=>{if(!active)return;if(drag){stop(e);const p=planePoint(e,data.sector);if(p){if(!drag.changed){beforeChange();drag.changed=true}data[drag.index?'b':'a']=p;update()}return}if(data&&!data.b){const p=point(e,data.sector);hover=p?.point||null;update()}canvas.style.cursor=data?.b?(cast(e,ends)[0]?'grab':''): 'crosshair'}, {capture:true});
 canvas.addEventListener('pointerup',e=>{if(!active||!down||down.id!==e.pointerId)return;const d=down;down=null;if(drag){drag=null;controls.enabled=true;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);stop(e);return}if(data?.b)return;controls.enabled=true;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);stop(e);if(Math.hypot(e.clientX-d.x,e.clientY-d.y)>7)return;const p=point(e,data?.sector??null);if(!p){hint.textContent='Choose a point on the same wall. Use New to measure another wall.';return}if(!data){data={sector:p.sector,a:p.point,b:null};hover=null}else{const m=rulerMetrics(data.a,p.point);if(m.distance<.01){hint.textContent='Choose a point at least 1 cm away.';return}beforeChange();data.b=p.point;hover=null}status();update()}, {capture:true});
 canvas.addEventListener('pointercancel',()=>{cancelDrag();update()});canvas.addEventListener('pointerleave',()=>{if(!drag){hover=null;update()}});window.addEventListener('blur',()=>{cancelDrag();update()});
 window.addEventListener('keydown',e=>{if(!active||['INPUT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();setActive(false)}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();e.stopImmediatePropagation();clear()}}, {capture:true});
 let drawingKey='';
 function update(){if(!data){group.visible=false;label.hidden=true;return}const face=sectors[data.sector].face;face.add(group);face.updateWorldMatrix(true,false);const a=v(data.a),b=v(data.b||hover||data.a);const pos=face.localToWorld(a.clone());const front=new THREE.Vector3(0,0,1).transformDirection(face.matrixWorld).dot(camera.position.clone().sub(pos))>0;group.visible=front;
  const metrics=rulerMetrics(data.a,data.b||hover||data.a),key=[...a.toArray(),...b.toArray()].join(',');if(key!==drawingKey){drawingKey=key;setLine(line,[a,b]);const delta=b.clone().sub(a),normal=new THREE.Vector3(-delta.y,delta.x,0).normalize(),points=[];for(let t=.1;t<metrics.distance;t+=.1){const p=a.clone().lerp(b,t/metrics.distance),length=Math.round(t*10)%5===0?.045:.025;points.push(p.clone().addScaledVector(normal,-length),p.clone().addScaledVector(normal,length))}setLine(ticks,points);const radius=Math.min(.27,metrics.distance*.30),sx=metrics.dx<0?-1:1,sy=metrics.dy<0?-1:1;setLine(base,[a,a.clone().add(new THREE.Vector3(sx*radius*1.25,0,0))]);const arcPoints=[];for(let i=0;i<=24;i++){const theta=metrics.angle*Math.PI/180*i/24;arcPoints.push(a.clone().add(new THREE.Vector3(sx*Math.cos(theta)*radius,sy*Math.sin(theta)*radius,0)))}setLine(arc,arcPoints)}
  ends[0].position.copy(a);ends[1].position.copy(b);ends[1].visible=!!(data.b||hover);for(const end of ends){const wp=face.localToWorld(end.position.clone());const scale=camera.position.distanceTo(wp)*2*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))/canvas.clientHeight*7;end.scale.setScalar(scale)}
  const midpoint=face.localToWorld(a.clone().add(b).multiplyScalar(.5)).project(camera);label.hidden=!front||midpoint.z>1||metrics.distance<.01;label.style.left=((midpoint.x+1)/2*canvas.clientWidth)+'px';label.style.top=((1-midpoint.y)/2*canvas.clientHeight)+'px';readout.textContent=`${metrics.distance.toFixed(2)} m · ${metrics.angle.toFixed(0)}°`;label.title=`Wall-plane distance. ${Math.abs(metrics.dx).toFixed(2)} m across, ${Math.abs(metrics.dy).toFixed(2)} m up/down. Angle from wall horizontal. Photo measurements depend on correct wall scale.`;label.dataset.distance=metrics.distance.toFixed(6);label.dataset.angle=metrics.angle.toFixed(6);label.dataset.wall=String(data.sector);
 }
 return{update,setActive,get active(){return active},getData:()=>data?.b?structuredClone(data):null,load(value){cancelDrag();data=value&&Number.isInteger(value.sector)&&sectors[value.sector]&&[value.a,value.b].every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))?structuredClone(value):null;hover=null;drawingKey='';status();update()}};
}
